package com.vault.dto;import jakarta.validation.constraints.*;import java.time.Instant;public final class Requests{private Requests(){}public record Register(@NotBlank @Size(max=120)String name,@Email @NotBlank String email,@Size(min=10,max=72)String password){}public record Login(@Email @NotBlank String email,@NotBlank String password){}public record CreateKey(@NotBlank String serviceName,@NotBlank @Size(max=120)String keyName,@NotBlank @Size(max=1024)String apiKey,@NotBlank String environment,@Size(max=500)String description,Instant expiresAt){}public record UpdateKey(@NotBlank String serviceName,@NotBlank @Size(max=120)String keyName,@NotBlank String environment,@Size(max=500)String description,Instant expiresAt){}public record Reveal(@NotBlank String password){}public record Rotate(@NotBlank @Size(max=1024)String apiKey){}public record Profile(@NotBlank @Size(max=120)String name){}public record ChangePassword(@NotBlank String currentPassword,@Size(min=10,max=72)String newPassword){}}
